  moods: {
    key: string
    value: MoodEntry
  }
}

const DB_NAME = 'rhythm'
const DB_VERSION = 1

let dbPromise: Promise<IDBPDatabase<RhythmDB>> | null = null

export function getDB(): Promise<IDBPDatabase<RhythmDB>> {
  if (!dbPromise) {
    dbPromise = openDB<RhythmDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('habits')) {
          db.createObjectStore('habits', { keyPath: 'id' })
        }
        if (!db.objectStoreNames.contains('completions')) {
          const store = db.createObjectStore('completions', {
            keyPath: ['habitId', 'date'],
          })
          store.createIndex('by-habit', 'habitId')
          store.createIndex('by-date', 'date')
        }
        if (!db.objectStoreNames.contains('moods')) {
          db.createObjectStore('moods', { keyPath: 'date' })
        }
      },
    })
  }
  return dbPromise
}

export interface Snapshot {
  habits: Habit[]
  completions: Completion[]
  moods: MoodEntry[]
}

export async function loadSnapshot(): Promise<Snapshot> {
  const db = await getDB()
  const [habits, completions, moods] = await Promise.all([
    db.getAll('habits'),
    db.getAll('completions'),
    db.getAll('moods'),
  ])
  habits.sort((a, b) => a.order - b.order || a.createdAt.localeCompare(b.createdAt))
  return { habits, completions, moods }
}

export async function putHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', habit)
}

/** Remove a habit together with all of its completions, atomically. */
export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  const tx = db.transaction(['habits', 'completions'], 'readwrite')
  const index = tx.objectStore('completions').index('by-habit')
  for await (const cursor of index.iterate(id)) {
    await cursor.delete()
  }
  await tx.objectStore('habits').delete(id)
  await tx.done
}

export async function setCompletion(
  habitId: string,
  date: string,
  done: boolean,
): Promise<void> {
  const db = await getDB()
  if (done) {
    await db.put('completions', { habitId, date })
  } else {
    await db.delete('completions', [habitId, date])
  }
}

export async function putMood(entry: MoodEntry): Promise<void> {
  const db = await getDB()
  await db.put('moods', entry)
}

import { useCallback, useEffect, useState } from 'react'
import type { ThemePreference } from '../types'

const STORAGE_KEY = 'rhythm:theme'

function readStored(): ThemePreference {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'light' || stored === 'dark' || stored === 'system') {
      return stored
    }
  } catch {
    /* storage can be unavailable — fall through to system */
  }
  return 'system'
}

function prefersDark(): boolean {
  return (
    typeof window !== 'undefined' &&
    window.matchMedia('(prefers-color-scheme: dark)').matches
  )
}

export interface ThemeController {
  preference: ThemePreference
  resolved: 'light' | 'dark'
  isDark: boolean
  setTheme: (next: ThemePreference) => void
}

export function useTheme(): ThemeController {
  const [preference, setPreference] = useState<ThemePreference>(readStored)
  const [systemDark, setSystemDark] = useState<boolean>(prefersDark)

  useEffect(() => {
    const query = window.matchMedia('(prefers-color-scheme: dark)')
    const onChange = (event: MediaQueryListEvent) => setSystemDark(event.matches)
    query.addEventListener('change', onChange)
    return () => query.removeEventListener('change', onChange)
  }, [])

  const resolved: 'light' | 'dark' =
    preference === 'system' ? (systemDark ? 'dark' : 'light') : preference

  useEffect(() => {
    const root = document.documentElement
    root.classList.toggle('dark', resolved === 'dark')
  }, [resolved])

  const setTheme = useCallback((next: ThemePreference) => {
    setPreference(next)
    try {
      localStorage.setItem(STORAGE_KEY, next)
    } catch {
      /* ignore storage failures */
    }
  }, [])

  return { preference, resolved, isDark: resolved === 'dark', setTheme }
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  deleteHabit,
  loadSnapshot,
  putHabit,
  putMood,
  setCompletion,
  type Snapshot,
} from '../db'
import { todayKey } from '../lib/date'
import type { Completion, Habit, MoodEntry } from '../types'

const EMPTY: Snapshot = { habits: [], completions: [], moods: [] }

/**
 * Central data layer. Loads the snapshot once, keeps it in memory, and writes
 * every change back to IndexedDB. The app is fully offline after first load.
 */
export function useData() {
  const [snapshot, setSnapshot] = useState<Snapshot>(EMPTY)
  const [ready, setReady] = useState(false)

  useEffect(() => {
    loadSnapshot().then((s) => {
      setSnapshot(s)
      setReady(true)
    })
  }, [])

  const refresh = useCallback(() => {
    loadSnapshot().then(setSnapshot)
  }, [])

  const habits = snapshot.habits
  const completionsByHabit = useMemo(() => {
    const map = new Map<string, Set<string>>()
    for (const c of snapshot.completions) {
      const set = map.get(c.habitId) ?? new Set<string>()
      set.add(c.date)
      map.set(c.habitId, set)
    }
    return map
  }, [snapshot.completions])

  const moodByKey = useMemo(() => {
    const map = new Map<string, MoodEntry>()
    for (const m of snapshot.moods) map.set(m.date, m)
    return map
  }, [snapshot.moods])

  const isDone = useCallback(
    (habitId: string, date: string): boolean =>
      completionsByHabit.get(habitId)?.has(date) ?? false,
    [completionsByHabit],
  )

  const toggleCompletion = useCallback(
    (habitId: string, date: string) => {
      const done = isDone(habitId, date)
      const nextCompletions = snapshot.completions.filter(
        (c) => !(c.habitId === habitId && c.date === date),
      )
      if (!done) {
        nextCompletions.push({ habitId, date })
      }
      setSnapshot((s) => ({ ...s, completions: nextCompletions }))
      setCompletion(habitId, date, !done)
    },
    [isDone, snapshot.completions],
  )

  const addHabit = useCallback(
    (input: { name: string; emoji: string; color: string }) => {
      const habit: Habit = {
        id: crypto.randomUUID(),
        name: input.name.trim(),
        emoji: input.emoji || '🌱',
        color: input.color,
        createdAt: todayKey(),
        order: snapshot.habits.length,
      }
      setSnapshot((s) => ({ ...s, habits: [...s.habits, habit] }))
      putHabit(habit)
    },
    [snapshot.habits.length],
  )

  const renameHabit = useCallback(
    (id: string, name: string) => {
      const habit = snapshot.habits.find((h) => h.id === id)
      if (!habit) return
      const updated = { ...habit, name: name.trim() }
      setSnapshot((s) => ({
        ...s,
        habits: s.habits.map((h) => (h.id === id ? updated : h)),
      }))
      putHabit(updated)
    },
    [snapshot.habits],
  )

  const setHabitColor = useCallback(
    (id: string, color: string) => {
      const habit = snapshot.habits.find((h) => h.id === id)
      if (!habit) return
      const updated = { ...habit, color }
      setSnapshot((s) => ({
        ...s,
        habits: s.habits.map((h) => (h.id === id ? updated : h)),
      }))
      putHabit(updated)
    },
    [snapshot.habits],
  )

  const removeHabit = useCallback(
    (id: string) => {
      setSnapshot((s) => ({
        ...s,
        habits: s.habits.filter((h) => h.id !== id),
        completions: s.completions.filter((c) => c.habitId !== id),
      }))
      deleteHabit(id)
    },
    [],
  )

  const setMood = useCallback(
    (date: string, mood: number, note?: string) => {
      const entry: MoodEntry = { date, mood, ...(note ? { note } : {}) }
      setSnapshot((s) => {
        const others = s.moods.filter((m) => m.date !== date)
        return { ...s, moods: [...others, entry] }
      })
      putMood(entry)
    },
    [],
  )

  return {
    ready,
    habits,
    moodByKey,
    isDone,
    toggleCompletion,
    addHabit,
    renameHabit,
    setHabitColor,
    removeHabit,
    setMood,
  }
}

export type DataLayer = ReturnType<typeof useData>

