          {habit.emoji}
        </span>

        <div className="min-w-0 flex-1">
          <button
            onClick={() => setManaging(true)}
            className="block max-w-[220px] text-left text-base font-medium tracking-tight truncate"
          >
            <span
              className={cn(
                'transition-opacity',
                done ? 'opacity-48' : 'opacity-100',
              )}
            >
              {habit.name}
            </span>
          </button>
          <div className="mt-0.5 flex items-center gap-1.5 text-xs text-[var(--color-ink-muted)]">
            <span
              className="inline-block h-1.5 w-1.5 rounded-full"
              style={{ backgroundColor: tone }}
            />
            {streak.current > 0 ? `${streak.current} Tag${streak.current > 1 ? 'e' : ''} Serie` : 'Noch keine Serie'}
          </div>
        </div>

        <button
          onClick={() => setManaging(true)}
          aria-label="Habit verwalten"
          className="text-[var(--color-ink-faint)] opacity-0 transition-opacity group-hover:opacity-100 focus:opacity-100"
        >
          <IconGear width={20} height={20} />
        </button>
      </li>

      <ManageHabit
        habit={habit}
        tone={tone}
        streak={streak}
        open={managing}
        onClose={() => setManaging(false)}
        data={data}
      />
    </>
  )
}

function ManageHabit({
  habit,
  tone,
  streak,
  open,
  onClose,
  data,
}: {
  habit: Habit
  tone: string
  streak: ReturnType<typeof computeStreaks>
  open: boolean
  onClose: () => void
  data: DataLayer
}) {
  return (
    <Modal open={open} onClose={onClose}>
      <div className="flex items-center gap-3 mb-5">
        <span className="text-2xl">{habit.emoji}</span>
        <h2 className="text-lg font-semibold tracking-tight flex-1">{habit.name}</h2>
      </div>

      <div className="mb-6 flex gap-6 rounded-xl bg-[var(--color-surface-2)] px-4 py-3.5">
        <Stat label="Aktuelle Serie" value={streak.current > 0 ? `${streak.current}d` : '—'} />
        <Stat label="Längste Serie" value={streak.longest > 0 ? `${streak.longest}d` : '—'} />
        <Stat label="Gesamt" value={`${streak.total}×`} />
      </div>

      <div className="mb-7">
        <span className="text-xs font-medium tracking-wide text-[var(--color-ink-muted)] mb-2 block">
          Farbe
        </span>
        <div className="flex flex-wrap gap-3">
          {HABIT_COLORS.map((c) => (
            <button
              key={c.id}
              onClick={() => data.setHabitColor(habit.id, c.value)}
              aria-label={`Farbe ${c.label}`}
              aria-pressed={habit.color === c.value}
              className={cn(
                'h-9 w-9 rounded-full transition-transform',
                habit.color === c.value && 'scale-110',
              )}
              style={{ backgroundColor: c.value }}
            />
          ))}
        </div>
      </div>

      <button
        onClick={() => {
          data.removeHabit(habit.id)
          onClose()
        }}
        className="flex w-full items-center justify-center gap-2 rounded-xl border border-[var(--color-line)] px-4 py-3 text-base font-medium text-[var(--color-ink)] transition-colors hover:bg-[var(--color-surface-2)]"
      >
        <IconTrash width={18} height={18} />
        Habit löschen
      </button>
    </Modal>
  )
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex-1 text-center">
      <p className="text-lg font-semibold tracking-tight">{value}</p>
      <p className="mt-0.5 text-xs text-[var(--color-ink-muted)]">{label}</p>
    </div>
  )
}

import { useState } from 'react'
import type { DataLayer } from '../hooks/useData'
import type { ThemeController } from '../hooks/useTheme'
import { todayKey, formatFullDate, formatRelative } from '../lib/date'
import { computeStreaks } from '../lib/streaks'
import { MOODS, moodMeta } from '../lib/colors'
import { HabitItem } from './HabitItem'
import { HabitForm } from './HabitForm'
import { EmptyState } from './EmptyState'
import { IconPlus } from './icons'

export function Today({
  data,
  theme,
}: {
  data: DataLayer
  theme: ThemeController
}) {
  const [adding, setAdding] = useState(false)
  const key = todayKey()

  const completedCount = data.habits.filter((h) => data.isDone(h.id, key)).length
  const mood = data.moodByKey.get(key)

  return (
    <div>
      <header className="mb-5">
        <p className="text-sm font-medium text-[var(--color-ink-muted)]">
          {formatRelative(key)}
        </p>
        <h1 className="mt-1 text-2xl font-semibold tracking-tight">
          {formatFullDate(key)}
        </h1>
      </header>

      {data.habits.length === 0 && !adding ? (
        <EmptyState
          title="Noch keine Habits"
          description="Lege dein erstes Habit an und markiere es täglich. Deine Serien bauen sich von selbst auf."
          action={
            <button
              onClick={() => setAdding(true)}
              className="flex w-full items-center justify-center gap-2 rounded-xl bg-[var(--color-ink)] px-4 py-3.5 text-base font-medium text-white"
            >
              <IconPlus width={19} height={19} />
              Erstes Habit anlegen
            </button>
          }
        />
      ) : (
        <>
          {data.habits.length > 0 && (
            <div className="mb-5 flex items-baseline justify-between">
              <span className="text-sm font-medium text-[var(--color-ink-muted)]">
                Fortschritt
              </span>
              <span className="text-sm font-semibold tracking-tight">
                {completedCount} von {data.habits.length}
              </span>
            </div>
          )}

          <ul className="space-y-2.5">
            {data.habits.map((habit) => (
              <HabitItem
                key={habit.id}
                habit={habit}
                done={data.isDone(habit.id, key)}
                onToggle={() => data.toggleCompletion(habit.id, key)}
                data={data}
                theme={theme}
              />
            ))}
          </ul>

          {data.habits.length > 0 && (
            <button
              onClick={() => setAdding(true)}
              aria-label="Weiteres Habit anlegen"
              className="mt-2.5 flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-[var(--color-line)] py-3 text-sm font-medium text-[var(--color-ink-muted)] transition-colors hover:border-[var(--color-accent)] hover:text-[var(--color-accent)]"
            >
              <IconPlus width={17} height={17} />
              Habit hinzufügen
            </button>
          )}
        </>
      )}

      <MoodCheckIn mood={mood?.mood} onSet={(v) => data.setMood(key, v)} />

      <HabitForm
        open={adding}
        onClose={() => setAdding(false)}
        onSubmit={data.addHabit}
      />
    </div>
  )
}

function MoodCheckIn({
  mood,
  onSet,
}: {
  mood?: number
  onSet: (v: number) => void
}) {
  return (
    <section className="mt-6 rounded-2xl border border-[var(--color-line)] bg-[var(--color-surface)] px-4 py-4">
      <div className="mb-3 flex items-center justify-between">
        <span className="text-xs font-medium tracking-wide text-[var(--color-ink-muted)]">
          Wie fühlt du dich?
        </span>
        {mood && (
          <span className="text-xs font-medium text-[var(--color-accent)]">
            {moodMeta(mood).label}
          </span>
        )}
      </div>
      <div className="flex justify-between gap-1">
        {MOODS.map((m) => {
          const active = mood === m.value
          return (
            <button
              key={m.value}
              onClick={() => onSet(m.value)}
              aria-label={`Stimmung ${m.label}`}
              aria-pressed={active}
              className={cls(
                'flex flex-1 flex-col items-center gap-1.5 rounded-xl py-2.5 transition-colors',
                active && 'bg-[var(--color-accent-soft)]',
              )}
            >
              <span className="text-xl leading-none">{m.emoji}</span>
              <span
                className={cls(
                  'text-[10px] font-medium tracking-wide transition-colors',
                  active ? 'text-[var(--color-accent)]' : 'text-[var(--color-ink-faint)]',
                )}
              >
                {m.label}
              </span>
            </button>
          )
        })}
      </div>
    </section>
  )
}

function cls(...parts: Array<string | false | null>) {
  return parts.filter(Boolean).join(' ')
}

import {
  Bar,
  BarChart,
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
} from 'recharts'
import type { DataLayer } from '../hooks/useData'
import type { ThemeController } from '../hooks/useTheme'
import {
  addDays,
  formatDayMonth,
  lastNDays,
  weekdayShort,
} from '../lib/date'
import { computeStreaks } from '../lib/streaks'
import { moodMeta } from '../lib/colors'
import { EmptyState } from './EmptyState'

const ACCENT = '#4a6a4f'
const ACCENT_SOFT = '#8fae86'

export function Week({
  data,
  theme,
}: {
  data: DataLayer
  theme: ThemeController
}) {
  const keys = lastNDays(7)

  const chartData = keys.map((key) => {
    const done = data.habits.filter((h) => data.isDone(h.id, key)).length
    const mood = data.moodByKey.get(key)?.mood
    return {
      key,
      label: `${weekdayShort(key)}\n${formatDayMonth(key).replace(/ \d{2}\./, '')}`,
      completions: done,
      mood: mood ?? null,
    }
  })

  const weekCompletions = data.completions.filter((c) =>
    keys.includes(c.date),
  ).length
  const moodsThisWeek = keys.filter((k) => data.moodByKey.has(k)).length

  if (data.habits.length === 0 && data.moods.length === 0) {
    return (
      <EmptyState
        title="Noch keine Daten"
        description="Sobald du Habits abhakest und deine Stimmung einträgst, erscheint hier der Verlauf der letzten sieben Tage."
      />
    )
  }

  return (
    <div>
      <header className="mb-5">
        <h1 className="text-2xl font-semibold tracking-tight">Wochenrückblick</h1>
        <p className="mt-1 text-sm text-[var(--color-ink-muted)]">
          Letzte 7 Tage · {weekCompletions} erledigt · {moodsThisWeek} Stimmungs-Einträge
        </p>
      </header>

      <section className="mb-8">
        <h2 className="mb-3 text-xs font-medium tracking-wide text-[var(--color-ink-muted)]">
          Erledigte Habits pro Tag
        </h2>
        <div className="h-44">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} barSize={26} ariaStatic>
              <CartesianGrid
                vertical={false}
                stroke="rgba(0,0,0,0.06)"
                strokeWidth={1}
                strokeDasharray="4 4"
                translateY={-8}
              />
              <XAxis
                dataKey="label"
                axisLine={false}
                tickLine={false}
                tick={{ fontSize: 12, fill: '#6f6d69' }}
                dy={8}
              />
              <Tooltip
                contentStyle={{
                  background: theme.isDark ? '#232220' : '#fff',
                  border: '1px solid rgba(0,0,0,0.08)',
                  borderRadius: 12,
                  boxShadow: '0 8px 24px rgba(0,0,0,0.10)',
                  fontSize: 13,
                }}
                cursor={{ fill: 'rgba(0,0,0,0.04)', radius: 8 }}
              />
              <Bar
                dataKey="completions"
                fill={ACCENT}
                radius={[6, 6, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      <section>
        <h2 className="mb-3 text-xs font-medium tracking-wide text-[var(--color-ink-muted)]">
          Stimmung
        </h2>
        <div className="h-44">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} ariaStatic>
              <CartesianGrid
                vertical={false}
                stroke="rgba(0,0,0,0.06)"
                strokeWidth={1}
                strokeDasharray="4 4"
                translateY={-8}
              />
              <XAxis
                dataKey="label"
                axisLine={false}
                tickLine={false}
                tick={{ fontSize: 12, fill: '#6f6d69' }}
                dy={8}
              />
              <Tooltip
                contentStyle={{
                  background: theme.isDark ? '#232220' : '#fff',
                  border: '1px solid rgba(0,0,0,0.08)',
                  borderRadius: 12,
                  boxShadow: '0 8px 24px rgba(0,0,0,0.10)',
                  fontSize: 13,
                }}
              />
              <Line
                type="monotone"
                dataKey="mood"
                stroke={ACCENT_SOFT}
                strokeWidth={2.5}
                dot={{ r: 4, fill: ACCENT, stroke: '#fff', strokeWidth: 2 }}
                activeDot={{ r: 6, fill: ACCENT, stroke: '#fff', strokeWidth: 2 }}
                connectNulls
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
        {data.moods.length === 0 && (
          <p className="mt-2 text-xs text-[var(--color-ink-faint)]">
            Keine Stimmungseinträge in den letzten 7 Tagen.
          </p>
        )}
      </section>
    </div>
  )
}

import type { DataLayer } from '../hooks/useData'
import type { ThemeController } from '../hooks/useTheme'
import { themeLabels, themeIcons } from './theme-options'
import { EmptyState } from './EmptyState'
import { IconFlask } from './icons'

export function Settings({
  data,
  theme,
}: {
  data: DataLayer
  theme: ThemeController
}) {
  const total = data.completions.length
  const withMood = data.moods.length

  return (
    <div>
      <header className="mb-5">
        <h1 className="text-2xl font-semibold tracking-tight">Einstellungen</h1>
      </header>

      <section className="mb-8">
        <h2 className="mb-3 text-xs font-medium tracking-wide text-[var(--color-ink-muted)]">
          Design
        </h2>
        <div className="rounded-2xl border border-[var(--color-line)] bg-[var(--color-surface)] divide-y divide-[var(--color-line)]">
          {(['system', 'light', 'dark'] as const).map((value) => {
            const active = theme.preference === value
            return (
              <button
                key={value}
                onClick={() => theme.setTheme(value)}
                aria-pressed={active}
                className="flex w-full items-center gap-3 px-4 py-3.5 text-left"
              >
                <span className="text-[var(--color-ink-muted)]">
                  {themeIcons[value]({ width: 20, height: 20 })}
                </span>
                <span className="flex-1 text-base font-medium tracking-tight">
                  {themeLabels[value]}
                </span>
                <span
                  className={
                    'h-4.5 w-4.5 rounded-full border-2 transition-colors ' +
                    (active
                      ? 'border-[var(--color-accent)] bg-[var(--color-accent)]'
                      : 'border-[var(--color-line)]')
                  }
                >
                  {active && (
                    <svg viewBox="0 0 24 24" className="text-white absolute">
                      <path
                        d="M4 12.5l4.5 4L20 6"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth={2.5}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  )}
                </span>
              </button>
            )
          })}
        </div>
      </section>

      <section>
        <h2 className="mb-3 text-xs font-medium tracking-wide text-[var(--color-ink-muted)]">
          Deine Daten
        </h2>
        {data.habits.length === 0 ? (
          <EmptyState
            title="Noch keine Habits"
            description="Lege Habits an, damit hier Statistiken erscheinen."
          />
        ) : (
          <div className="rounded-2xl border border-[var(--color-line)] bg-[var(--color-surface)] px-4 py-3.5 space-y-2.5">
            <DataRow label="Habits" value={`${data.habits.length}`} />
            <DataRow label="Erledigungen gesamt" value={`${total}`} />
            <DataRow label="Tage mit Stimmung" value={`${withMood}`} />
            <DataRow label="Speicherung" value="Lokal (Offline)" />
          </div>
        )}
      </section>

      <div className="mt-6 flex items-center justify-center gap-1.5 text-xs text-[var(--color-ink-faint)]">
        <IconFlask width={14} height={14} />
        Rhythm · offlinefähig
      </div>
    </div>
  )
}

function DataRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-[var(--color-ink-muted)]">{label}</span>
      <span className="font-medium tracking-tight">{value}</span>
    </div>
  )
}

